    topic("File I/O", "Standard library", "standard_library_api", "intermediate", "The stdio API opens a stream, performs checked I/O, and closes it.", "FILE *file = fopen(path, mode);\n...\nfclose(file);", "Use it for bounded text or binary file operations.", "Check fopen and every important read/write result; always close a successful stream.", examples("c", [("Open and write", "beginner", "#include <stdio.h>\nint main(void) { FILE *f = fopen(\"notes.txt\", \"w\"); if (!f) return 1; fputs(\"saved\\n\", f); fclose(f); }", "Write one line to a local file.", "C17 compiler and writable directory", "saved", "file contains saved", "The mode w truncates an existing file."), ("Read a line", "beginner", "#include <stdio.h>\nint main(void) { char line[32]; FILE *f = fopen(\"notes.txt\", \"r\"); if (f && fgets(line, sizeof line, f)) puts(line); if (f) fclose(f); }", "Read into a bounded buffer.", "C17 compiler and existing file", "saved", "saved", "fgets limits the number of bytes written to the buffer."), ("Append", "intermediate", "FILE *f = fopen(\"events.log\", \"a\");\nif (f) { fputs(\"event\\n\", f); fclose(f); }", "Add without replacing existing content.", "C17 compiler and writable directory", "event", "event appended", "Append mode positions writes at the end."), ("Binary size", "intermediate", "size_t written = fwrite(buffer, 1, length, file);\nif (written != length) { /* handle error */ }", "Write a known byte count.", "C17 compiler", "buffer and length", "full byte count or error", "Compare the returned count with the requested count."), ("Error path", "advanced", "FILE *f = fopen(\"missing.txt\", \"r\");\nif (!f) { perror(\"missing.txt\"); return 1; }\nfclose(f);", "Report an operating-system error.", "C17 compiler", "missing path", "diagnostic on stderr", "perror adds the library error description." )]), purpose="Use the C standard I/O contract with bounded buffers and checked failures."),
