    topic("Grid", "Layout", "css_property", "intermediate", "CSS Grid places content in rows and columns with explicit or responsive tracks.", ".grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem; }", "Use it for card catalogs, dashboards, and two-dimensional layouts.", "Use minmax(0, 1fr) to prevent long content from forcing overflow.", examples("css", [("Three columns", "beginner", ".catalog { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem; }", "Create a desktop card grid.", "Modern browser", "catalog cards", "three equal columns", "minmax allows tracks to shrink safely."), ("Two areas", "beginner", ".layout { display: grid; grid-template-columns: 1fr 18rem; gap: 2rem; }", "Place main content beside a sidebar.", "Modern browser", "main and aside", "main plus sidebar", "The fixed sidebar value should be suitable for the viewport."), ("Auto fit", "intermediate", ".cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr)); }", "Let the grid adapt to available width.", "Modern browser", "cards", "responsive columns", "Choose a minimum card width that remains readable."), ("Named areas", "advanced", ".page { grid-template-areas: \"header header\" \"main aside\"; }", "Document a page layout with named regions.", "Modern browser", "page regions", "named placement", "Every named area must form a rectangle."), ("Mobile change", "professional", "@media (max-width: 48rem) { .layout { grid-template-columns: 1fr; } }", "Collapse a two-column layout on small screens.", "Modern browser", "narrow viewport", "single column", "Test actual content at the breakpoint, not only empty boxes.")]), purpose="Build two-dimensional responsive layouts without brittle widths."),
