FAMILY_BY_SLUG = {
    "python": "python", "python-for-ai": "python", "c-programming": "c", "cpp-programming": "cpp", "java": "java", "advanced-java": "java",
    "javascript": "javascript", "typescript": "javascript", "node-js": "javascript", "jquery": "javascript",
    "sql": "sql", "mysql": "sql", "postgresql": "sql", "sqlite": "sql", "mongodb": "sql", "redis": "sql",
    "linux": "devops", "git": "devops", "github": "devops", "docker": "devops", "ci-cd": "devops", "aws": "devops", "microsoft-azure": "devops",
    "html": "html", "css": "css", "algorithms": "cs", "data-structures": "cs", "operating-systems": "cs",
    "cybersecurity-fundamentals": "security", "web-security": "security", "owasp-top-10": "security", "secure-coding": "security",
    "react": "react", "react-native": "react",
}


def family_for(course: Course):
    return FAMILY_BY_SLUG.get(course.slug)


def slugify(value: str) -> str:
    return "".join(char.lower() if char.isalnum() else "-" for char in value).strip("-").replace("--", "-")


def main():
    db = SessionLocal()
    admin_id = db.scalar(select(User.id).where(User.role.in_(("super_admin", "platform_admin", "admin"))).order_by(User.created_at).limit(1))
    inserted = 0
    courses = db.scalars(select(Course).where(Course.published.is_(True)).order_by(Course.slug)).all()
    for course in courses:
        family = family_for(course)
        blueprints = EXTRA.get(course.slug) if course.slug in EXTRA else None
        if blueprints is None:
            if not family:
                continue
            blueprints = {"python": PYTHON, "javascript": JAVASCRIPT, "sql": SQL, "devops": DEVOPS, "c": C, "cpp": CPP, "java": JAVA, "html": HTML, "css": CSS, "react": REACT, "cs": CS, "security": SECURITY}[family]
        for order, blueprint in enumerate(blueprints, 1):
            slug = slugify(blueprint["title"])
            if db.scalar(select(SyntaxReference.id).where(SyntaxReference.course_id == course.id, SyntaxReference.slug == slug)):
                continue
            row = SyntaxReference(course_id=course.id, title=blueprint["title"], slug=slug, category=blueprint["category"], description=blueprint["description"], basic_syntax=blueprint["basic_syntax"], when_to_use=blueprint["when_to_use"], important_notes=blueprint["important_notes"], reference_type=blueprint["reference_type"], difficulty=blueprint["difficulty"], purpose=blueprint["purpose"], syntax_format=blueprint["syntax_format"], version_compatibility=blueprint["version_compatibility"], common_mistakes=blueprint["common_mistakes"], best_practices=blueprint["best_practices"], practice_exercises=blueprint["practice_exercises"], further_reading=blueprint["further_reading"], minimum_examples=5, status="published", display_order=order, published_at=datetime.now(timezone.utc), created_by=admin_id, updated_by=admin_id)
            db.add(row); db.flush()
            for item in blueprint["examples"]:
                db.add(SyntaxReferenceExample(reference_id=row.id, **item))
            db.flush()
            db.add(SyntaxReferenceVersion(reference_id=row.id, version=1, status="published", snapshot_json=json.dumps({"title": row.title, "slug": row.slug, "source": "reviewed seed"}), created_by=admin_id))
            inserted += 1
    db.commit()
    print(f"inserted={inserted} published English references across {len(courses)} published courses")
    db.close()


if __name__ == "__main__":
    main()
